export function analyzeStereo(buffer,bins=128){const n=buffer.length;if(!Number.isInteger(n)||n<1||![1,2].includes(buffer.numberOfChannels)||!Number.isInteger(bins)||bins<1||bins>4096)throw Error('PCM invalide');const l=buffer.getChannelData(0),r=buffer.numberOfChannels===2?buffer.getChannelData(1):l;if(l.length!==n||r.length!==n)throw Error('Canal incomplet');let ll=0,rr=0,lr=0,mid=0;const envelope=Array(Math.min(bins,n)).fill(0);for(let i=0;i<n;i++){const a=l[i],b=r[i];if(!Number.isFinite(a)||!Number.isFinite(b))throw Error('PCM non fini');ll+=a*a;rr+=b*b;lr+=a*b;mid+=((a+b)/2)**2;const k=Math.floor(i*envelope.length/n);envelope[k]=Math.max(envelope[k],Math.abs(a),Math.abs(b));}return {correlation:ll&&rr?Math.max(-1,Math.min(1,lr/Math.sqrt(ll*rr))):null,monoLossDb:ll+rr?(mid?10*Math.log10(mid/((ll+rr)/2)):null):null,completeMonoCancellation:mid===0&&ll+rr>0,envelope};}
export function spectrum(buffer,size=1024,offset=0){if(!Number.isInteger(size)||size<32||size>2048||size%2||!Number.isInteger(offset)||offset<0||offset+size>buffer.length)throw Error('Fenêtre invalide');const a=buffer.getChannelData(0);const out=[];for(let k=0;k<=size/2;k++){let re=0,im=0;for(let i=0;i<size;i++){const x=a[offset+i]*(.5-.5*Math.cos(2*Math.PI*i/(size-1))),p=2*Math.PI*k*i/size;re+=x*Math.cos(p);im-=x*Math.sin(p)}out.push({hz:k*buffer.sampleRate/size,magnitude:Math.hypot(re,im)/size});}return out;}